def __repr__(self):
        cn = self.__class__.__name__
        parts = []
        if self.wrapped:
            parts.append('wrapped=%r' % self.wrapped)
        if self.recursive:
            parts.append('recursive=True')
        if not self.echo:
            parts.append('echo=False')
        if self.breakpoint:
            parts.append('breakpoint=%r' % (self.breakpoint if self.breakpoint is not pdb.set_trace else True))
        if self.post_mortem:
            parts.append('post_mortem=%r' % (self.post_mortem if self.post_mortem is not pdb.post_mortem else True))
        if not parts:
            return '%s()' % cn
        return '%s(%s)' % (cn, ', '.join(parts))
